import{_ as t,o,c as i,a0 as n}from"./chunks/framework.CKZJaUMN.js";const g=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/concepts.md","filePath":"explanation/concepts.md"}'),a={name:"explanation/concepts.md"};function s(r,e,d,c,h,p){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>The whole substrate is three primitives — <strong>entity</strong>, <strong>op</strong>, <strong>snapshot</strong> — plus the planes and stores around them. Get these and the rest is plumbing.</p><h2 id="entity" tabindex="-1">Entity <a class="header-anchor" href="#entity" aria-label="Permalink to &quot;Entity&quot;">​</a></h2><p><code>{id, kind, node, indexDoc, health}</code></p><ul><li><code>kind</code> — free-form tag; the integration&#39;s namespace (<code>sepia-session</code>, <code>campaign</code>, …).</li><li><code>indexDoc</code> — opaque JSON for list views. Hypha merges and columnizes it; meaning belongs to the integration.</li><li><code>health</code> — liveness/lock state reported by the owner node.</li></ul><h2 id="op" tabindex="-1">Op <a class="header-anchor" href="#op" aria-label="Permalink to &quot;Op&quot;">​</a></h2><p><code>{entity, kind, payload}</code> — submitted to an entity&#39;s <strong>owner node</strong>.</p><ul><li><code>kind</code> is namespaced <code>&lt;integration&gt;.&lt;verb&gt;</code> (<code>sepia.prompt</code>, <code>campaign.start</code>); <code>entity.*</code> is the reserved substrate namespace (<code>entity.delete</code> only, today).</li><li><code>payload</code> is opaque to hypha — the owning plane interprets it.</li><li>Ops are idempotent-keyed and TTL&#39;d in the outbox; <code>Turn</code>-class ops dead-letter on first failure.</li></ul><h2 id="snapshot" tabindex="-1">Snapshot <a class="header-anchor" href="#snapshot" aria-label="Permalink to &quot;Snapshot&quot;">​</a></h2><p><code>{entity, ref, bytes}</code> — the migration primitive.</p><p>Serialize on the owner (<code>GET /api/entities/{id}/snapshot</code>), import on the target (<code>POST /api/entities/snapshot</code>). Bytes are opaque end-to-end; resume semantics are the integration&#39;s (<code>campaign-snapshot/v1</code>, sepia session IR export, …).</p><h2 id="why-generic" tabindex="-1">Why generic <a class="header-anchor" href="#why-generic" aria-label="Permalink to &quot;Why generic&quot;">​</a></h2><p>The distributed abilities — sync, arbitration, outbox, transfer, pairing — are orchestration-domain but workload-agnostic. Shaping them around sessions was the mistake ADR-0091 corrected; shaping them around <em>entities</em> is what lets CI jobs, sturn claims, or cicada schedules become kinds without touching this repo.</p><h2 id="around-the-primitives" tabindex="-1">Around the primitives <a class="header-anchor" href="#around-the-primitives" aria-label="Permalink to &quot;Around the primitives&quot;">​</a></h2><ul><li><strong>Node</strong> — a <code>hypha serve</code> host owning a set of entity kinds via its <code>KindRegistry</code>. The node is the unit of ownership: an entity lives on exactly one node at a time.</li><li><strong>Hub</strong> — <code>hypha-hub</code>, the aggregation gateway: merged entity index, op routing with offline outbox, SSE diff tail, push.</li><li><strong>Owner</strong> — the node an entity&#39;s ops route to; arbitration (<code>hypha-control</code>) decides who may drive entity X on node Y.</li><li><strong>Outbox</strong> — <code>hypha-outbox</code>, a durable per-entity FIFO SQLite queue that replays oldest-first when a node reconnects.</li><li><strong>Projection</strong> — <code>hypha-sync</code>&#39;s SQLite entity-index + sync engine on the hub side; reads merge through it.</li><li><strong>Kind / integration</strong> — a workload registers <code>kind=&quot;&lt;name&gt;&quot;</code> entities by implementing the entity-plane contract in its own repo (sepia&#39;s <code>sepia-peregrin</code>, peregrin&#39;s <code>campaign</code>). Hypha never names the kind.</li><li><strong>KV</strong> — node-local <code>{ns}/{key}</code> → JSON store (<code>hypha-kv</code> + <code>-file</code>) with per-namespace visibility — the generalization of peregrin&#39;s config/projects surface.</li></ul>',15)])])}const u=t(a,[["render",s]]);export{g as __pageData,u as default};
